[asy]
usepackage("amsmath");
unitsize(0.5 cm);

int i, j, n;

for (int i = 0; i <= 9; ++i) {
for (int j = 0; j <= 9; ++j) {
  if (i + j <= 9) {
    n = choose(i + j,i);
    if (n % 2 == 0) {label("$\boxed{" + string(n) + "}$", i*(-1,-1) + j*(1,-1));}
    if (n % 2 == 1) {label("$" + string(n) + "$", i*(-1,-1) + j*(1,-1));}
  }
}}
[/asy]

